window.kbPageData["views/entry/k-89b4dc89398ac031"] = {"key":"entry/k-89b4dc89398ac031","state":{"route":"entry/k-89b4dc89398ac031"},"node":{"id":"k-89b4dc89398ac031","mode":"k","title":"《关于推行常住地提供基本公共服务的实施意见》（5 月 22 日）","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment","governance","modern"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["重要文件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《关于推行常住地提供基本公共服务的实施意见》（5 月 22 日）","slug":"6eeed3344ecc"}],"directorySummary":"考点十二 《关于推行常住地提供基本公共服务的实施意见》（5 月 22 日）\n由常住地提供基本公共服务，逐步消除基本公共服务与户籍挂钩因素，促进未落户常住人口与\n户籍人口同等享有基本公共服务，促进基本公共服务均等化水平明显提升，有力支撑深入实施\n以人为本的新型城镇化战略。部署六大公共服务：加强随迁子女…","sources":[{"id":"8f65da4c26e86ec6","label":"《关于推行常住地提供基本公共服务的实施意见》（5 月 22 日）","topic":"重要文件","category":"时政","text":"考点十二 《关于推行常住地提供基本公共服务的实施意见》（5 月 22 日）\n由常住地提供基本公共服务，逐步消除基本公共服务与户籍挂钩因素，促进未落户常住人口与\n户籍人口同等享有基本公共服务，促进基本公共服务均等化水平明显提升，有力支撑深入实施\n以人为本的新型城镇化战略。部署六大公共服务：加强随迁子女教育保障、扩大公租房保障范\n围、健全就业地参加职工社会保险制度（全面取消就业地参保户籍限制）、加强常住地基本医\n疗保障、强化就业基本公共服务、完善兜底性基本公共服务；并提出优化设施布局、梯度供\n给、财政转移支付、用地配置、共建共享、协同经办（省内通办、跨省通办）、常住人口登记\n统计等支持保障措施。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":14,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"},{"slug":"employment","title":"就业质量与社会保障"},{"slug":"governance","title":"基层治理与群众参与"}],"units":{"k-89b4dc89398ac031":[]}};
